            offsets=[int(row.split(':',1)[0]) for row in rows]+[len(compressed)]
            for start,end in zip(offsets,offsets[1:]):
                frame=compressed[start:end]
                self.assertEqual(zstd.get_frame_size(frame),len(frame))
