                changed_items=[dict(items[0],sha1='0'*40)]
                b.cached_shard_dump(changed_items,root,workspace)
                self.assertEqual(stage.call_count,7)
                with patch.object(b,'DUMP_STAGING_VERSION','page-aligned-zstd-parallel-v3'):
                    b.cached_shard_dump(changed_items,root,workspace)
