                        exp=dest/'.bundle-expander';exp.mkdir(parents=True);(dest/'.incomplete').write_text('expander ready')
                        (exp/'page-index.tsv').write_text('0\n1\n');(exp/'dict-bundle-expander').write_text('worker');write_namespace_fixture(exp)
