class FigureBorrowDigestReuseTests(unittest.TestCase):
    setUp = CompleteParentTupleReplayTests.setUp
    selection = ImmutableCaptureBorrowTests.selection

    def verified_guard(self):
        import copy
        result = b.validated_figure_tuple(self.paths, self.fixture.wiki, self.fixture.date)
        key = tuple(sorted((name, str(path.absolute())) for name, path in self.paths.items()))
        guard = copy.deepcopy(b._FIGURE_TUPLE_REPLAYS[key][0])
        return guard, dict(next(iter(result.values()))[1])

    def test_guarded_borrow_eliminates_duplicate_hash_calls_and_bytes_with_identical_input_maps(self):
        guard, inventory = self.verified_guard()
        covered = {Path(path) for path in guard[1]}
        roles = self.selection(self.fixture.root/'native-reuse')
        cold = self.selection(self.fixture.root/'native-cold')
        self.assertFalse(covered & set(roles.inputs))
        original = b.sha256_file
        cold_reads, reused_reads = [], []
        def counted(rows, path):
            if path in covered:
                rows.append((path, path.stat().st_size))
            return original(path)
        with patch.object(b, 'sha256_file', side_effect=lambda path: counted(cold_reads, path)):
            for path in sorted(covered):
                cold.bind_input(path)
        hashes = {name: guard[1][str(path)][1]['sha256'] for name, path in self.paths.items()}
        with patch.object(b, 'sha256_file', side_effect=lambda path: counted(reused_reads, path)), \
                patch.object(b, 'copy_verified_snapshot', side_effect=AssertionError('Borrowed Figure copy')):
            pinned = b.pinned_auxiliary_snapshots(self.paths, hashes,
                self.fixture.root/'borrowed-workspace', borrower=roles)
        self.assertEqual(pinned, self.paths)
        self.assertEqual(len(cold_reads), len(covered))
        self.assertEqual(sum(size for _, size in cold_reads), sum(row[1]['size'] for row in guard[1].values()))
        self.assertGreater(sum(size for _, size in cold_reads), 0)
        self.assertEqual(reused_reads, [])
        for path in covered:
            self.assertEqual(roles.inputs[path], cold.inputs[path])
            self.assertEqual(roles.input_identities[path], cold.input_identities[path])
        self.assertIn(self.args.sql[0], covered)
        self.assertIn(self.parent, roles.borrowed_capture_directories)
        self.assertIn(self.child, roles.borrowed_capture_directories)
        roles.require_unchanged()

    def test_uncovered_and_unknown_fingerprint_inputs_keep_ordinary_hashing(self):
        import copy
        guard, inventory = self.verified_guard()
        path = self.paths['figure-sizing-raw']
        original = b.sha256_file
        for mode in ('uncovered', 'future-schema', 'invalid-size', 'invalid-sha1'):
            with self.subTest(mode=mode):
                selected = copy.deepcopy(guard)
                if mode == 'uncovered':
                    del selected[1][str(path)]
                elif mode == 'future-schema':
                    selected[1][str(path)][1]['future'] = True
                elif mode == 'invalid-size':
                    selected[1][str(path)][1]['size'] = True
                else:
                    selected[1][str(path)][1]['sha1'] = 'invalid'
                roles = self.selection(self.fixture.root/('native-'+mode))
                with patch.object(b, 'sha256_file', wraps=original) as hashed:
                    roles.bind_capture(self.args.output, inventory, figure_guard=selected)
                self.assertEqual([Path(call.args[0]) for call in hashed.call_args_list].count(path), 1)
                self.assertEqual(roles.input_identities[path]['sha256'], inventory[path.name])
                roles.require_unchanged()

    def test_uncovered_digest_failure_does_not_publish_reused_entries(self):
        guard, inventory = self.verified_guard()
        path = self.paths['figure-sizing-raw']
        del guard[1][str(path)]
        inventory[path.name] = '0'*64
        roles = self.selection(self.fixture.root/'native-bad-uncovered')
        covered = {Path(name) for name in guard[1]}
        self.assertFalse(covered & set(roles.inputs))
        with self.assertRaisesRegex(ValueError, 'differs from validated bytes'):
            roles.bind_capture(self.args.output, inventory, figure_guard=guard)
        self.assertFalse(covered & set(roles.inputs))
        self.assertFalse(covered & set(roles.input_identities))

    def test_guarded_capture_rejects_changed_bytes_replacement_symlink_mode_membership_and_sql(self):
        path = self.paths['figure-sizing-raw']
        for mode in ('bytes', 'replacement', 'symlink', 'mode', 'membership', 'sql'):
            with self.subTest(mode=mode):
                b._FIGURE_TUPLE_REPLAYS.clear()
                guard, inventory = self.verified_guard()
                roles = self.selection(self.fixture.root/('native-before-'+mode))
                covered = {Path(name) for name in guard[1]}
                selected = self.args.sql[0] if mode == 'sql' else path
                raw, permissions = selected.read_bytes(), stat.S_IMODE(selected.stat().st_mode)
                extra = self.args.output/'unrecorded.raw'
                replacement = self.fixture.root/'replacement.raw'
                try:
                    if mode in ('bytes', 'sql'):
                        selected.write_bytes(raw+b' ')
                    elif mode == 'replacement':
                        replacement.write_bytes(raw); replacement.chmod(permissions); replacement.replace(selected)
                    elif mode == 'symlink':
                        replacement.write_bytes(raw); selected.unlink(); selected.symlink_to(replacement)
                    elif mode == 'mode':
                        selected.chmod(permissions ^ stat.S_IXUSR)
                    else:
                        extra.write_bytes(b'unrecorded')
                    with self.assertRaises((ValueError, OSError)):
                        roles.bind_capture(self.args.output, inventory, figure_guard=guard)
                    self.assertFalse(covered & set(roles.inputs))
                finally:
                    if selected.is_symlink(): selected.unlink()
                    selected.write_bytes(raw); selected.chmod(permissions)
                    extra.unlink(missing_ok=True); replacement.unlink(missing_ok=True)

    def test_changes_during_uncovered_hashing_cannot_publish_reused_guard_authority(self):
        uncovered = self.paths['figure-sizing-raw']
        guarded = self.args.sql[0]
        original_hash = b.sha256_file
        for mode in ('sql-bytes', 'sql-replacement', 'membership', 'helper'):
            with self.subTest(mode=mode):
                b._FIGURE_TUPLE_REPLAYS.clear()
                guard, inventory = self.verified_guard()
                del guard[1][str(uncovered)]
                roles = self.selection(self.fixture.root/('native-during-'+mode))
                covered = {Path(name) for name in guard[1]}
                raw, permissions = guarded.read_bytes(), stat.S_IMODE(guarded.stat().st_mode)
                extra = self.args.output/'unrecorded-during.raw'
                replacement = self.fixture.root/'sql-replacement.raw'
                changed = False
                def hashed(path):
                    nonlocal changed
                    value = original_hash(path)
                    if path == uncovered:
                        changed = True
                        if mode == 'sql-bytes': guarded.write_bytes(raw+b' ')
                        elif mode == 'sql-replacement':
                            replacement.write_bytes(raw); replacement.chmod(permissions); replacement.replace(guarded)
                        elif mode == 'membership': extra.write_bytes(b'unrecorded')
                    return value
                producer = self.figures.producer
                def observed_producer():
                    return 'changed helper' if mode == 'helper' and changed else producer()
                try:
                    with patch.object(b, 'sha256_file', side_effect=hashed), \
                            patch.object(self.figures, 'producer', side_effect=observed_producer):
                        with self.assertRaises((ValueError, OSError)):
                            roles.bind_capture(self.args.output, inventory, figure_guard=guard)
                    self.assertTrue(changed)
                    self.assertFalse(covered & set(roles.inputs))
                    self.assertFalse(covered & set(roles.input_identities))
                finally:
                    guarded.write_bytes(raw); guarded.chmod(permissions)
                    extra.unlink(missing_ok=True); replacement.unlink(missing_ok=True)

    def test_reused_entries_remain_bound_by_normal_dispatch_mutation_checks(self):
        guard, inventory = self.verified_guard()
        roles = self.selection(self.fixture.root/'native-after')
        roles.bind_capture(self.args.output, inventory, figure_guard=guard)
        roles.require_unchanged()
        source = self.args.sql[0]
        original = source.read_bytes()
        source.write_bytes(original+b' ')
        with self.assertRaisesRegex(ValueError, 'changed'):
            roles.require_unchanged()
        with self.assertRaisesRegex(ValueError, 'changed'):
            roles.bind_capture(self.args.output, inventory, figure_guard=guard)


class PreparedFigureVerdictTests(unittest.TestCase):
    setUp = CompleteParentTupleReplayTests.setUp
    validate = CompleteParentTupleReplayTests.validate

    @contextlib.contextmanager
    def selected(self):
        # Real recursive Figure/SQL/raw authorities; only the surrounding
        # qualified Python inventory is a small local source fixture.
        root=self.fixture.root/'verdict-source';(root/'tools').mkdir(parents=True,exist_ok=True)
        helper=root/'tools/verdict_fixture.py';helper.write_text('VALUE=1\n')
        inventory=_initial_sealed_write(root/'inventory.json',dict(head='original-source',
            files={'tools/verdict_fixture.py':_initial_sealed_reference(helper)},
            modes={'tools/verdict_fixture.py':0o644}))
        cfg=dict(source=dict(head='original-source',fingerprint='a'*64,inventory=inventory),
            date=self.fixture.date,edition_options={self.fixture.wiki:dict(
                auxiliary_snapshots={name:_initial_sealed_reference(path) for name,path in self.paths.items()})})
        with patch.object(b,'PROJECT',root):yield cfg,helper

    def test_optional_absent_or_partial_selection_does_not_offer_authority(self):
        with self.selected() as (cfg,_):
            self.validate();proof=b.prepared_figure_verdict(cfg)
            for snapshots in (None,{}, {'figure-sizing':str(self.paths['figure-sizing'])}):
                with self.subTest(snapshots=snapshots):
                    changed=copy.deepcopy(cfg)
                    changed['edition_options'][self.fixture.wiki]['auxiliary_snapshots']=snapshots
                    self.assertIsNone(b.prepared_figure_verdict(changed))
                    self.assertFalse(b.reuse_prepared_figure_verdict(changed,proof))
            malformed=copy.deepcopy(proof);malformed['version']=True
            self.assertFalse(b.reuse_prepared_figure_verdict(cfg,malformed))

    def test_successful_child_verdict_avoids_second_semantic_replay_but_parent_rehashes_complete_readset(self):
        with self.selected() as (cfg,_),patch.object(self.figures,'verify_tuple',wraps=self.figures.verify_tuple) as replay:
            expected=self.validate();self.assertEqual(replay.call_count,1)
            verdict=b.prepared_figure_verdict(cfg);self.assertIsNotNone(verdict)
            child_guard=next(iter(b._FIGURE_TUPLE_REPLAYS.values()))[0]
            b._FIGURE_TUPLE_REPLAYS.clear()
            with patch.object(self.figures.evidence,'fingerprint',wraps=self.figures.evidence.fingerprint) as hashes:
                self.assertTrue(b.reuse_prepared_figure_verdict(cfg,verdict))
            paths=[Path(call.args[0]) for call in hashes.call_args_list]
            self.assertEqual(set(map(str,paths)),set(child_guard[1]))
            self.assertEqual(paths.count(self.args.sql[0]),1)
            self.assertIn(self.parent/self.figures.ROLES['figure-sizing-raw'],paths)
            self.assertEqual(self.validate(),expected);self.assertEqual(replay.call_count,1)
            print('PREPARED_FIGURE_VERDICT_COUNTER '+json.dumps(dict(child_semantic_replays=1,
                parent_semantic_replays=0,parent_fresh_hashes=len(paths),wall_time_saving_claimed=False)))

    def test_no_successful_validator_return_means_no_transferable_verdict(self):
        with self.selected() as (cfg,_):
            self.assertIsNone(b.prepared_figure_verdict(cfg))
            with patch.object(self.figures,'verify_tuple',side_effect=ValueError('original semantic failure')):
                with self.assertRaisesRegex(ValueError,'original semantic failure'):self.validate()
            self.assertFalse(b._FIGURE_TUPLE_REPLAYS)
            self.assertIsNone(b.prepared_figure_verdict(cfg))
            self.assertFalse(b.reuse_prepared_figure_verdict(cfg,None))
            with patch.object(self.figures,'verify_tuple',wraps=self.figures.verify_tuple) as replay:
                self.validate();self.assertEqual(replay.call_count,1)

    def test_missing_foreign_malformed_or_stale_proof_uses_normal_validation(self):
        with self.selected() as (cfg,_):
            self.validate();verdict=b.prepared_figure_verdict(cfg)
            for mode in ('missing','version','source','catalog','edition','date','paths','guard','result-context','helper'):
                with self.subTest(mode=mode):
                    proof=copy.deepcopy(verdict)
                    if mode=='missing':proof=None
                    elif mode=='version':proof['version']=1
                    elif mode=='source':proof['source']['fingerprint']='b'*64
                    elif mode=='catalog':proof['python_tooling']={}
                    elif mode=='edition':proof['edition']='foreignwiktionary'
                    elif mode=='date':proof['date']='20990101'
                    elif mode=='paths':proof['paths'].pop(next(iter(proof['paths'])))
                    elif mode=='guard':proof['guard_sha256']='0'*64
                    elif mode=='result-context':next(iter(proof['result'].values()))[0]['wiki']='foreignwiktionary'
                    else:
                        foreign=copy.deepcopy(next(iter(b._FIGURE_TUPLE_REPLAYS.values()))[0])
                        foreign[0][0]['generator_sha256']='0'*64
                        proof['guard_sha256']=b._prepared_figure_guard_digest(foreign,proof['version'])
                    b._FIGURE_TUPLE_REPLAYS.clear()
                    self.assertFalse(b.reuse_prepared_figure_verdict(cfg,proof))
                    self.assertFalse(b._FIGURE_TUPLE_REPLAYS)
                    with patch.object(self.figures,'verify_tuple',wraps=self.figures.verify_tuple) as replay:
                        self.validate();self.assertEqual(replay.call_count,1)

    def test_mutated_sql_parent_external_raw_and_replacement_cannot_transfer(self):
        record=json.loads(self.observation.read_text())
        external=self.observation.parent/next(iter(record['artifacts']))
        raw=self.parent/self.figures.ROLES['figure-sizing-raw']
        for mode,path in (('sql',self.args.sql[0]),('raw',raw),('external',external),
                          ('same-bytes-new-inode',raw),('membership',self.parent/'unexpected-member')):
            with self.subTest(mode=mode),self.selected() as (cfg,_):
                b._FIGURE_TUPLE_REPLAYS.clear();self.validate();proof=b.prepared_figure_verdict(cfg)
                original=None if mode=='membership' else path.read_bytes()
                try:
                    if mode=='same-bytes-new-inode':
                        replacement=path.with_name(path.name+'.new');replacement.write_bytes(original);replacement.replace(path)
                    else:path.write_bytes(b'extra' if original is None else original+b'changed')
                    b._FIGURE_TUPLE_REPLAYS.clear()
                    self.assertFalse(b.reuse_prepared_figure_verdict(cfg,proof))
                    self.assertFalse(b._FIGURE_TUPLE_REPLAYS)
                    # Fallback still executes the maintained validator; a
                    # changed invalid source cannot inherit previous success.
                    with patch.object(self.figures,'verify_tuple',wraps=self.figures.verify_tuple) as replay:
                        if mode=='same-bytes-new-inode':self.validate()
                        else:
                            with self.assertRaises((ValueError,KeyError,UnicodeError,OSError)):self.validate()
                        self.assertEqual(replay.call_count,1)
                finally:
                    if original is None:path.unlink()
                    else:path.write_bytes(original)

    def test_python_source_and_change_during_fresh_hash_refuse_before_publication(self):
        for mode in ('validator-source','mid-hash'):
            with self.subTest(mode=mode),self.selected() as (cfg,helper):
                b._FIGURE_TUPLE_REPLAYS.clear();self.validate();proof=b.prepared_figure_verdict(cfg)
                b._FIGURE_TUPLE_REPLAYS.clear()
                if mode=='validator-source':helper.write_text('VALUE=2\n')
                original=self.figures.evidence.fingerprint;changed=[]
                def fingerprint(path):
                    result=original(path)
                    if mode=='mid-hash' and not changed:
                        changed.append(True);helper.write_text('VALUE=2\n')
                    return result
                with patch.object(self.figures.evidence,'fingerprint',side_effect=fingerprint):
                    with self.assertRaisesRegex(ValueError,'Python helper changed'):
                        b.reuse_prepared_figure_verdict(cfg,proof)
                self.assertFalse(b._FIGURE_TUPLE_REPLAYS)

