class CanonicalFigureOverlapTests(unittest.TestCase):
    setUp=ImmutableFigureBorrowTests.setUp
    selection=ImmutableCaptureBorrowTests.selection

    def test_alias_introduced_after_eligibility_refuses_before_capture_binding(self):
        roles=self.selection(self.fixture.root/'native-late-alias')
        hashes={role:b.sha256_file(path)for role,path in self.paths.items()}
        source=self.args.sql[0];original=source.read_bytes()
        moved=source.with_name(source.name+'.held-original')
        owned=self.fixture.root/'owned';owned.mkdir()
        target=owned/source.name;target.write_bytes(original)
        bind=roles.bind_capture;entered=[]
        def changed(*values,**options):
            source.rename(moved);source.symlink_to(target);entered.append(True)
            return bind(*values,**options)
        try:
            with patch.object(roles,'bind_capture',side_effect=changed),patch.object(b,'copy_verified_snapshot',side_effect=AssertionError('Changed authority must not reach copying')):
                with self.assertRaisesRegex(ValueError,'Unsafe|changed'):
                    b.pinned_auxiliary_snapshots(self.paths,hashes,self.fixture.root/'workspace',borrower=roles,owned_roots=(owned,))
            self.assertEqual(entered,[True])
            self.assertFalse(getattr(roles,'borrowed_capture_directories',{}))
            self.assertNotIn(source,roles.inputs)
            self.assertFalse((self.fixture.root/'workspace').exists())
        finally:
            if source.is_symlink():source.unlink()
            if moved.exists():moved.rename(source)
        self.assertEqual(source.read_bytes(),original)

    def test_owned_transitive_authority_keeps_original_verified_copy_failure(self):
        roles=self.selection(self.fixture.root/'native-owned-copy')
        hashes={role:b.sha256_file(path)for role,path in self.paths.items()}
        originals={path:path.read_bytes()for path in self.paths.values()}
        failure=OSError('original verified copy failure')
        with patch.object(roles,'bind_capture',side_effect=AssertionError('Owned authority must not be borrowed')),patch.object(b,'copy_verified_snapshot',side_effect=failure):
            with self.assertRaises(OSError)as caught:
                b.pinned_auxiliary_snapshots(self.paths,hashes,self.fixture.root/'workspace',borrower=roles,owned_roots=(self.parent,))
        self.assertIs(caught.exception,failure)
        self.assertFalse(getattr(roles,'borrowed_capture_directories',{}))
        for path,raw in originals.items():self.assertEqual(path.read_bytes(),raw)

class RetainedCompilerIdentityReuseTests(unittest.TestCase):
    fixture = RetainedNativeRoleTests.fixture

    def test_build_identity_reuses_only_verified_compiler_bytes(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            roles, compiler, expected = self.selection(root)
            alias = root / 'zig-path'
            alias.symlink_to(compiler)
            with patch.object(b, 'source_fingerprint', return_value=expected['source']), \
                    patch.object(b, 'sha256_file', wraps=b.sha256_file) as digest:
                def identify(selected):
                    return b.build_input_identity([], str(alias), {}, None, 60000, native_roles=selected)

                retained = identify(roles)
                self.assertEqual(retained['native_tool_roles'], expected['native_tool_roles'])
                self.assertEqual(retained['zig_sha256'], expected['zig_sha256'])
                self.assertNotIn(call(compiler), digest.call_args_list)
                self.assertNotIn(call(alias), digest.call_args_list)
                self.assertEqual(identify(None)['zig_sha256'], expected['zig_sha256'])
                self.assertIn(call(alias), digest.call_args_list)

                foreign = root / 'other-zig'
                foreign.write_bytes(b'other compiler')
                foreign.chmod(0o755)
                alias.unlink()
                alias.symlink_to(foreign)
                with self.assertRaisesRegex(ValueError, 'Selected compiler differs'):
                    identify(roles)
                self.assertIn(call(foreign), digest.call_args_list)

    def test_build_identity_refuses_compiler_replacement_during_source_check(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            roles, compiler, expected = self.selection(root)

            def replace_compiler():
                replacement = root / 'replacement'
                replacement.write_bytes(compiler.read_bytes())
                replacement.chmod(compiler.stat().st_mode)
                replacement.replace(compiler)
                return expected['source']

            with patch.object(b, 'source_fingerprint', side_effect=replace_compiler):
                with self.assertRaisesRegex(ValueError, 'dependency identity changed'):
                    b.build_input_identity([], str(compiler), {}, None, 60000, native_roles=roles)

    def selection(self, root):
        roles, compiler = self.fixture(root)
        selection = b.RetainedNativeToolRoles(roles, zig_sha256=b.sha256_file(compiler))
        identity = dict(source='qualified-source', zig_sha256=b.sha256_file(compiler),
                        native_tool_roles=selection.provenance())
        return selection, compiler, identity

    def prepare(self, root, selection, compiler, identity):
        return b.prepare_blob_tools(root/'workspace', str(compiler), 'testwiktionary', '20261001',
            identity, expander_args=['dump', str(root/'output'), '--expander-only'], retained_roles=selection)

    def test_bound_compiler_digest_reused_across_preparation_without_reading_bytes(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);selection,compiler,identity=self.selection(root);calls=[];reads=[];events=[]
            original=b.sha256_file
            def digest(path):
                reads.append(Path(path))
                return original(path)
            with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                 patch.object(b,'sha256_file',side_effect=digest), \
                 patch.object(b,'timed_run',side_effect=lambda argv,*a,**kw:calls.append(argv)), \
                 patch.object(b,'phase_event',side_effect=lambda *a,**kw:events.append(kw)):
                first=self.prepare(root,selection,compiler,identity)
                second=self.prepare(root,selection,compiler,identity)
            self.assertEqual(set(first),set(b.BLOB_TOOL_NAMES));self.assertEqual(first,second)
            self.assertEqual(len(calls),2);self.assertEqual(calls[0],calls[1])
            self.assertNotIn(compiler,reads)
            for record in (event for event in events if 'status' in event):
                self.assertEqual(record['status'],'success')
                self.assertEqual(record['zig_sha256'],identity['zig_sha256'])
                self.assertEqual(record['native_role_provenance'],identity['native_tool_roles'])
            selection.require_unchanged()

    def test_new_compiler_path_requires_actual_hash_before_digest_reuse(self):
        for different in (False,True):
            with self.subTest(different=different),tempfile.TemporaryDirectory() as tmp:
                root=Path(tmp);selection,compiler,identity=self.selection(root);reads=[];calls=[]
                alternate=root/'alternate-zig';alternate.write_bytes(b'foreign!' if different else compiler.read_bytes());alternate.chmod(0o755)
                original=b.sha256_file
                def digest(path):
                    if Path(path)==alternate:reads.append(Path(path))
                    return original(path)
                with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                     patch.object(b,'sha256_file',side_effect=digest), \
                     patch.object(b,'timed_run',side_effect=lambda argv,*a,**kw:calls.append(argv)),patch.object(b,'phase_event'):
                    if different:
                        with self.assertRaisesRegex(ValueError,'source or compiler differs'):
                            self.prepare(root,selection,alternate,identity)
                    else:self.prepare(root,selection,alternate,identity)
                self.assertEqual(reads,[alternate]);self.assertEqual(len(calls),0 if different else 1)
                self.assertEqual(selection.input_identities[alternate]['sha256'],original(alternate))

    def test_bound_compiler_changes_refuse_before_native_dispatch(self):
        for change in ('bytes-restored-mtime','same-bytes-replacement','mode'):
            with self.subTest(change=change),tempfile.TemporaryDirectory() as tmp:
                root=Path(tmp);selection,compiler,identity=self.selection(root);before=compiler.stat()
                if change=='bytes-restored-mtime':
                    compiler.write_bytes(b'changed!');os.utime(compiler,ns=(before.st_atime_ns,before.st_mtime_ns))
                elif change=='same-bytes-replacement':
                    other=root/'replacement';other.write_bytes(compiler.read_bytes());other.chmod(0o755);os.replace(other,compiler)
                else:compiler.chmod(0o555)
                with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                     patch.object(b,'timed_run') as dispatch,patch.object(b,'phase_event'):
                    with self.assertRaisesRegex(ValueError,'dependency identity changed'):
                        self.prepare(root,selection,compiler,identity)
                    dispatch.assert_not_called()

    def test_post_preparation_compiler_guard_rejects_identity_change_even_when_bytes_match(self):
        for change in ('same-bytes-replacement','bytes-restored-mtime','mode'):
            with self.subTest(change=change),tempfile.TemporaryDirectory() as tmp:
                root=Path(tmp);selection,compiler,identity=self.selection(root);calls=[];events=[];checks=[]
                def fingerprint():
                    checks.append(True)
                    if len(checks)==2:
                        before=compiler.stat()
                        if change=='same-bytes-replacement':
                            other=root/'replacement';other.write_bytes(compiler.read_bytes());other.chmod(0o755);os.replace(other,compiler)
                        elif change=='bytes-restored-mtime':
                            compiler.write_bytes(b'changed!');os.utime(compiler,ns=(before.st_atime_ns,before.st_mtime_ns))
                        else:compiler.chmod(0o555)
                    return identity['source']
                with patch.object(b,'source_fingerprint',side_effect=fingerprint), \
                     patch.object(b,'timed_run',side_effect=lambda argv,*a,**kw:calls.append(argv)), \
                     patch.object(b,'phase_event',side_effect=lambda *a,**kw:events.append(kw)):
                    with self.assertRaisesRegex(ValueError,'dependency identity changed'):
                        self.prepare(root,selection,compiler,identity)
                self.assertEqual(len(calls),1);self.assertEqual(len(checks),2)
                self.assertEqual(events[-1]['status'],'failure');self.assertNotIn('selected_native_artifacts',events[-1])

    def test_new_compiler_path_mutated_during_hash_cannot_be_bound(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);selection,compiler,identity=self.selection(root)
            alternate=root/'alternate-zig';alternate.write_bytes(compiler.read_bytes());alternate.chmod(0o755)
            original=b.sha256_file
            def digest(path):
                value=original(path)
                if Path(path)==alternate:
                    before=alternate.stat();alternate.write_bytes(b'changed!')
                    os.utime(alternate,ns=(before.st_atime_ns,before.st_mtime_ns))
                return value
            with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                 patch.object(b,'sha256_file',side_effect=digest),patch.object(b,'timed_run') as dispatch,patch.object(b,'phase_event'):
                with self.assertRaisesRegex(ValueError,'changed while hashing'):
                    self.prepare(root,selection,alternate,identity)
                dispatch.assert_not_called()
            self.assertNotIn(alternate,selection.inputs);self.assertNotIn(alternate,selection.input_identities)

    def test_bound_compiler_parent_alias_refuses_before_dispatch(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);roles,compiler=self.fixture(root)
            directory=root/'toolchain';directory.mkdir();compiler=compiler.rename(directory/'zig')
            for role in roles.values():
                role['dependencies']['zig']['path']=str(compiler)
            selection=b.RetainedNativeToolRoles(roles,zig_sha256=b.sha256_file(compiler))
            identity=dict(source='qualified-source',zig_sha256=b.sha256_file(compiler),native_tool_roles=selection.provenance())
            moved=root/'moved-toolchain';directory.rename(moved);directory.symlink_to(moved,target_is_directory=True)
            with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                 patch.object(b,'timed_run') as dispatch,patch.object(b,'phase_event'):
                with self.assertRaises(ValueError):self.prepare(root,selection,compiler,identity)
                dispatch.assert_not_called()

    def test_retained_source_change_and_native_failure_still_refuse_success(self):
        for failure in ('source','native'):
            with self.subTest(failure=failure),tempfile.TemporaryDirectory() as tmp:
                root=Path(tmp);selection,compiler,identity=self.selection(root);events=[]
                error=subprocess.CalledProcessError(7,['actual retained driver'],stderr=b'original failure')
                with patch.object(b,'source_fingerprint',side_effect=[identity['source'],'changed-source']), \
                     patch.object(b,'timed_run',side_effect=error if failure=='native' else None) as dispatch, \
                     patch.object(b,'phase_event',side_effect=lambda *a,**kw:events.append(kw)):
                    with self.assertRaises(ValueError if failure=='source' else subprocess.CalledProcessError) as caught:
                        self.prepare(root,selection,compiler,identity)
                    if failure=='native':self.assertIs(error,caught.exception)
                self.assertEqual(dispatch.call_count,1);self.assertEqual(events[-1]['status'],'failure')
                self.assertNotIn('selected_native_artifacts',events[-1])

    def test_nonretained_preparation_keeps_both_actual_compiler_reads(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);fixture=PreparedBlobToolsTests();workspace,compiler,identity=fixture.fixture(root);reads=[]
            original=b.sha256_file
            def digest(path):
                if Path(path)==compiler:reads.append(Path(path))
                return original(path)
            with patch.object(b,'source_fingerprint',return_value=identity['source']), \
                 patch.object(b,'sha256_file',side_effect=digest), \
                 patch.object(b,'run_checked',side_effect=fixture.install),patch.object(b,'phase_event'):
                tools=b.prepare_blob_tools(workspace,str(compiler),'testwiktionary','20261001',identity)
            self.assertEqual(set(tools),set(b.BLOB_TOOL_NAMES));self.assertEqual(reads,[compiler,compiler])

class LanguageMessagePairTests(unittest.TestCase):
    def test_pair_preserves_complete_state_and_replays_once_per_boundary(self):
        import prepare_language_messages as messages
        with tempfile.TemporaryDirectory() as tmp:
            snapshots=write_language_messages_fixture(Path(tmp))
            expected={name:b.validated_auxiliary_capture(name,path,'arwiktionary','20261001')
                      for name,path in snapshots.items()}
            with patch.object(messages,'verify',wraps=messages.verify) as verify:
                first=b._validated_auxiliary_state(snapshots,'arwiktionary','20261001')
                self.assertEqual(verify.call_count,1)
                second=b._validated_auxiliary_state(snapshots,'arwiktionary','20261001')
                self.assertEqual(verify.call_count,2)
            self.assertEqual(first,second)
            self.assertEqual(first[0],{name:b.sha256_file(path) for name,path in snapshots.items()})
            self.assertEqual({name:(row[0],row[1]) for name,row in first[1].items()},expected)

    def test_independent_roots_and_legacy_singles_keep_original_validation(self):
        import prepare_language_messages as messages
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);first=write_language_messages_fixture(root/'a');second=write_language_messages_fixture(root/'b')
            mixed={'interface-messages':first['interface-messages'],'language-fallbacks':second['language-fallbacks']}
            self.assertIsNone(b.validated_language_message_pair(mixed))
            with patch.object(messages,'verify',wraps=messages.verify) as verify:
                b._validated_auxiliary_state(mixed,'arwiktionary','20261001')
                self.assertEqual(verify.call_count,2)
            legacy=root/'interface-messages.tsv';legacy.write_text('en\tparentheses\t($1)\n')
            self.assertIsNone(b.validated_language_message_pair({'interface-messages':legacy}))
            self.assertEqual(b.verified_auxiliary_hashes({'interface-messages':legacy}),{'interface-messages':b.sha256_file(legacy)})

    def test_pair_requires_both_manifests_marker_and_exact_edition(self):
        import prepare_language_messages as messages
        for mutation in ('manifest','marker','edition','payload'):
            with self.subTest(mutation=mutation),tempfile.TemporaryDirectory() as tmp:
                snapshots=write_language_messages_fixture(Path(tmp));root=snapshots['interface-messages'].parent
                if mutation=='manifest':(root/'language-fallbacks.manifest.json').unlink()
                elif mutation=='marker':(root/messages.COMPLETE).unlink()
                elif mutation=='payload':snapshots['language-fallbacks'].write_bytes(b'corrupt')
                with self.assertRaises((ValueError,OSError)):
                    b._validated_auxiliary_state(snapshots,'wrongwiktionary' if mutation=='edition' else 'arwiktionary','20261001')

    def test_pair_refuses_transient_mutation_after_replay(self):
        with tempfile.TemporaryDirectory() as tmp:
            snapshots=write_language_messages_fixture(Path(tmp));pair=b.validated_language_message_pair(snapshots)
            path=snapshots['language-fallbacks'];original=path.read_bytes();path.write_bytes(original+b'x');path.write_bytes(original)
            with self.assertRaisesRegex(ValueError,'changed during auxiliary validation'):pair[1]()

    def test_pair_refuses_changes_between_roles_and_at_boundary_end(self):
        for target in ('language-fallbacks','interface-messages'):
            with self.subTest(target=target),tempfile.TemporaryDirectory() as tmp:
                snapshots=write_language_messages_fixture(Path(tmp));original=b.sha256_file;changed=False
                def digest(path):
                    nonlocal changed
                    value=original(path)
                    if Path(path)==snapshots[target] and not changed:
                        changed=True;Path(path).write_bytes(Path(path).read_bytes()+b'x')
                    return value
                with patch.object(b,'sha256_file',side_effect=digest):
                    with self.assertRaisesRegex(ValueError,'changed during auxiliary validation'):
                        b._validated_auxiliary_state(snapshots)

    def test_pair_refuses_unsafe_capture_names_and_aliases(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);snapshots=write_language_messages_fixture(root/'original')
            alias=root/'alias';alias.symlink_to(snapshots['interface-messages'].parent,target_is_directory=True)
            with self.assertRaises((ValueError,OSError)):
                b._validated_auxiliary_state({name:alias/path.name for name,path in snapshots.items()})
            manifest=snapshots['interface-messages'].with_suffix('.manifest.json')
            record=json.loads(manifest.read_text());record['artifacts']['../foreign']={'sha256':'0'*64}
            manifest.write_text(json.dumps(record))
            with self.assertRaisesRegex(ValueError,'Unsafe language/message capture inventory'):
                b.validated_language_message_pair(snapshots)


if __name__=='__main__':unittest.main()
